using UnityEngine;

namespace Astrea;

public class GameplayHandler : ReferenceSingleton<GameplayHandler>
{
	[Header("Assets")]
	[SerializeField]
	private SaveSystem saveSystem;

	[Header("Battle Speed Factor")]
	[SerializeField]
	private float battleSpeedDefault = 1f;

	[SerializeField]
	private float battleSpeedFast = 0.66f;

	[SerializeField]
	private float battleSpeedFaster = 0.33f;

	[SerializeField]
	private float battleSpeedUltraFast = 0.05f;

	[Header("Battle Speed Time Scale")]
	[SerializeField]
	private float timeScaleDefault = 1f;

	[SerializeField]
	private float timeScaleFast = 2f;

	[SerializeField]
	private float timeScaleFaster = 3.5f;

	[SerializeField]
	private float timeScaleUltraFast = 5f;

	[Header("Runtime")]
	[SerializeField]
	private int battleSpeedIndex;

	[SerializeField]
	private bool disableRewardsAnimation;

	public bool DisableRewardsAnimation => disableRewardsAnimation;

	private void Start()
	{
		battleSpeedIndex = saveSystem.LoadBattleSpeedSetting();
		disableRewardsAnimation = saveSystem.LoadDisableRewardAnimationsSetting();
	}

	public void OnBattleSpeedChanged(int battleSpeedIndex)
	{
		this.battleSpeedIndex = battleSpeedIndex;
	}

	public void OnDisableRewardAnimationsToggle(bool disableRewardsAnimation)
	{
		this.disableRewardsAnimation = disableRewardsAnimation;
	}

	public float GetBattleSpeedFactor()
	{
		if (battleSpeedIndex == 0)
		{
			return battleSpeedDefault;
		}
		if (battleSpeedIndex == 1)
		{
			return battleSpeedFast;
		}
		if (battleSpeedIndex == 2)
		{
			return battleSpeedFaster;
		}
		return battleSpeedUltraFast;
	}

	public float GetTimeScaleSpeed()
	{
		if (battleSpeedIndex == 0)
		{
			return timeScaleDefault;
		}
		if (battleSpeedIndex == 1)
		{
			return timeScaleFast;
		}
		if (battleSpeedIndex == 2)
		{
			return timeScaleFaster;
		}
		return timeScaleUltraFast;
	}

	public void SetTimeScaleSpeedBasedOnBattleSpeed()
	{
		if (!ReferenceSingleton<InputManager>.Instance.IsPaused)
		{
			Time.timeScale = GetTimeScaleSpeed();
		}
	}

	public void ResetTimeScale()
	{
		Time.timeScale = 1f;
	}
}
